<?php
declare(strict_types=1);
session_start();
$root=dirname(__DIR__,3);
$cfg=require $root.'/config.php';
date_default_timezone_set($cfg['timezone']??'America/Argentina/Buenos_Aires');
if(empty($_SESSION['user'])){header('Location:index.php');exit;}
$permissions=$_SESSION['user']['permissions']??[];
$isAdmin=($_SESSION['user']['role']??'')==='admin';
$canView=$isAdmin||!empty($permissions['projects']['view'])||!empty($permissions['projects']['manage']);
if(!$canView){http_response_code(403);exit('Tu perfil no permite acceder a proyectos.');}
require_once $root.'/app/Core/UnifiedSidebar.php';
$db=new PDO('mysql:host='.$cfg['db_host'].';dbname='.$cfg['db_name'].';charset=utf8mb4',$cfg['db_user'],$cfg['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
function et($v):string{return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$id=(int)($_GET['id']??0);
$s=$db->prepare('SELECT p.*,c.business_name,pp.business_name partner_name FROM projects p JOIN clients c ON c.id=p.client_id LEFT JOIN project_partners pp ON pp.id=p.partner_id WHERE p.id=?');
$s->execute([$id]);$project=$s->fetch();if(!$project){http_response_code(404);exit('Proyecto inexistente.');}
$s=$db->prepare('SELECT id,quote_category,version_no,quote_date,status,quote_families,quote_template_family FROM quotes WHERE project_id=? ORDER BY version_no DESC,id DESC');
$s->execute([$id]);$quotes=$s->fetchAll();
$categoryLabels=['general'=>'General','domotica'=>'Domótica','redes'=>'Redes','camaras'=>'Cámaras','alarma'=>'Alarma','audio'=>'Audio'];
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=et($project['project_number'])?> · Punto ERP</title><style><?=erpSidebarCss()?>body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.45 system-ui,-apple-system,Segoe UI,sans-serif}.main{margin-left:var(--sidebar);padding:32px 4%}.card{background:#fff;border:1px solid var(--line);border-radius:14px;padding:22px;margin-bottom:18px;box-shadow:0 4px 16px #00000008}.grid{display:grid;grid-template-columns:repeat(12,1fr);gap:16px}.c4{grid-column:span 4}.actions{display:flex;gap:9px;align-items:center;flex-wrap:wrap}.btn{display:inline-block;border:0;border-radius:8px;padding:10px 15px;background:var(--o);color:#fff;text-decoration:none;font-weight:700}.btn.light{background:#edf0f3;color:var(--ink)}.muted{color:var(--muted)}.pill{display:inline-block;padding:4px 9px;border-radius:20px;background:#edf0f3;font-size:12px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:11px 9px;border-bottom:1px solid var(--line);vertical-align:top}th{font-size:12px;text-transform:uppercase;color:var(--muted)}.info{font-size:18px;font-weight:700;margin-top:3px}@media(max-width:900px){.main{margin-left:0;padding:22px 18px}.c4{grid-column:span 12}}</style></head><body><?php erpSidebar('project');?><main class="main"><div class="actions"><div style="flex:1"><span class="muted"><?=et($project['business_name'])?><?=!empty($project['partner_name'])?' · '.et($project['partner_name']):''?></span><h1><?=et($project['project_number'])?> · <?=et($project['name'])?></h1></div><span class="pill"><?=et($project['status'])?></span></div><div class="grid"><div class="card c4"><span class="muted">Cliente</span><div class="info"><?=et($project['business_name'])?></div></div><div class="card c4"><span class="muted">Arquitecto / constructora</span><div class="info"><?=et($project['partner_name']?:'Sin asignar')?></div></div><div class="card c4"><span class="muted">Fecha de creación</span><div class="info"><?=!empty($project['created_at'])?et(date('d/m/Y',strtotime($project['created_at']))):'—'?></div></div></div><div class="card"><div class="actions"><div style="flex:1"><h2 style="margin:0">Presupuestos del proyecto</h2><p class="muted" style="margin:6px 0 0">Vista técnica: se muestran los equipos y trabajos incluidos, sin precios ni información financiera.</p></div></div><div class="scroll"><table><thead><tr><th>Rubro</th><th>Versión</th><th>Fecha</th><th>Estado</th><th>Tecnología</th><th>Acciones</th></tr></thead><tbody><?php foreach($quotes as $q):$family=trim((string)($q['quote_template_family']??''));if($family==='')$family=trim(explode(',',(string)($q['quote_families']??''))[0]??'');?><tr><td><span class="pill"><?=et($categoryLabels[$q['quote_category']]??$q['quote_category'])?></span></td><td>v<?=et($q['version_no'])?></td><td><?=et(date('d/m/Y',strtotime($q['quote_date'])))?></td><td><span class="pill"><?=et($q['status'])?></span></td><td><?=et($family?:'—')?></td><td><a class="btn light" href="?a=quote_view&id=<?=$q['id']?>">Ver detalle técnico</a></td></tr><?php endforeach;?></tbody></table><?php if(!$quotes):?><p class="muted">Este proyecto todavía no tiene presupuestos cargados.</p><?php endif;?></div></div></main></body></html>